        return []
    if len(match) == 1:
        return match
    name = author['name'].casefold()
    def priority(candidate):
        candidate_name = candidate['name'].casefold()
        alternate = [n.casefold() for n in candidate.get('alternate_names', [])]
        if candidate_name == name:
            rank = 0
        elif name in alternate:
            rank = 1
        else:
            rank = 2
        dates = sum(bool(author.get(k)) and bool(candidate.get(k)) for k in ('birth_date', 'death_date'))
        return (rank, -dates, key_int(candidate))
    return [min(match, key=priority)]


